import{_ as s,a,c as t,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · 单元 4 复习与自测 · 第73–80课","description":"L73–L96 原创练习和答案解析。","frontmatter":{"title":"第二册：实践与进步 · 单元 4 复习与自测 · 第73–80课","description":"L73–L96 原创练习和答案解析。","splitFrom":"life/english/new-concept/book-2/unit-04/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第二册：实践与进步 · 单元 4 复习与自测","summary":"L73–L96 原创练习和答案解析。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · 单元 4 复习与自测","link":"/life/english/new-concept/book-2/unit-04/review"},"next":{"text":"第二册：实践与进步 · 单元 4 复习与自测 · 第81–89课","link":"/life/english/new-concept/book-2/unit-04/review-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · 单元 4 复习与自测","link":"/life/english/new-concept/book-2/unit-04/review"},"next":{"text":"第二册：实践与进步 · 单元 4 复习与自测 · 第81–89课","link":"/life/english/new-concept/book-2/unit-04/review-part-02"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-04/review-part-01.md","filePath":"life/english/new-concept/book-2/unit-04/review-part-01.md"}'),i={name:"life/english/new-concept/book-2/unit-04/review-part-01.md"};function r(n,e,l,h,p,c){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="第二册-实践与进步-·-单元-4-复习与自测-·-第73–80课" tabindex="-1">第二册：实践与进步 · 单元 4 复习与自测 · 第73–80课 <a class="header-anchor" href="#第二册-实践与进步-·-单元-4-复习与自测-·-第73–80课" aria-label="Permalink to &quot;第二册：实践与进步 · 单元 4 复习与自测 · 第73–80课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-2/unit-04/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-2/unit-04/overview">单元导读</a> · <a href="/life/english/new-concept/book-2/unit-04/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-2/unit-04/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-2/unit-04/review">单元复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="第二册-实践与进步-·-单元-4-复习与自测" tabindex="-1">第二册：实践与进步 · 单元 4 复习与自测 <a class="header-anchor" href="#第二册-实践与进步-·-单元-4-复习与自测" aria-label="Permalink to &quot;第二册：实践与进步 · 单元 4 复习与自测 {#第二册-实践与进步-·-单元-4-复习与自测}&quot;">​</a></h2><p><a href="/life/english/new-concept/book-2/unit-04/overview">单元导读</a> · <a href="/life/english/new-concept/book-2/unit-04/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-2/unit-04/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-2/unit-04/review">单元复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-73-·-现在完成时与过去时间" tabindex="-1">Lesson 73 · 现在完成时与过去时间 <a class="header-anchor" href="#lesson-73-·-现在完成时与过去时间" aria-label="Permalink to &quot;Lesson 73 · 现在完成时与过去时间 {#lesson-73-·-现在完成时与过去时间}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Ella has crossed the border with her family five times this year.</p><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1 {#练习-1}&quot;">​</a></h3><p>填 cross：Ella has ___ the border five times.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> crossed</p><p><strong>解析：</strong> 完成时要求过去分词 crossed。</p></details><p><strong>表达迁移：</strong> 写一个学习或旅行纪录，交代统计时间、次数和能力边界。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Ella has crossed the border with her family five times this year. She can now explain the route to her younger brother. An adult still checks all the documents.</p><p>第一句的组织方式：has crossed 是完成时，five times 为次数，with her family 明确同行者，this year 的范围包含现在。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：five time 应为 five times；不要把 times 误译成五点钟。</p></details><p><a href="/life/english/new-concept/book-2/unit-04/lesson-073">回看本课</a></p><h2 id="lesson-74-·-定语从句与指代" tabindex="-1">Lesson 74 · 定语从句与指代 <a class="header-anchor" href="#lesson-74-·-定语从句与指代" aria-label="Permalink to &quot;Lesson 74 · 定语从句与指代 {#lesson-74-·-定语从句与指代}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The visitor who recognised the actor kept her secret.</p><h3 id="练习-1-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-1" aria-label="Permalink to &quot;练习 1 {#练习-1-1}&quot;">​</a></h3><p>能否省略 The visitor who recognised her 中的 who？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不能。</p><p><strong>解析：</strong> who 是定语从句主语，不能像宾语关系代词那样省略。</p></details><p><strong>表达迁移：</strong> 写一段尊重隐私的偶遇，使用 who 从句说明人物身份。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The visitor who recognised the actor kept her secret. They spoke briefly about the town. Nobody asked for a photograph.</p><p>第一句的组织方式：who 指 the visitor 并作 recognised 的主语；kept 是主句谓语，her 指前文 actor。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：The visitor who recognised the actor smiled. 中 who 作 recognised 的主语，意思是“认出演员的那位游客笑了”。The visitor who he recognised smiled. 也合法：he 作从句主语，who 作宾语，意思是“他认出的那位游客笑了”。若要表达前一种意思，不能写 The visitor who he recognised the actor smiled.；从句已有主语 he 和宾语 the actor，再加 who 会造成成分重复。</p></details><p><a href="/life/english/new-concept/book-2/unit-04/lesson-074">回看本课</a></p><h2 id="lesson-75-·-不定式与目的" tabindex="-1">Lesson 75 · 不定式与目的 <a class="header-anchor" href="#lesson-75-·-不定式与目的" aria-label="Permalink to &quot;Lesson 75 · 不定式与目的 {#lesson-75-·-不定式与目的}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The hikers laid bright jackets on the rocks to attract attention.</p><h3 id="练习-1-2" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-2" aria-label="Permalink to &quot;练习 1 {#练习-1-2}&quot;">​</a></h3><p>填 lay 的过去式：They ___ jackets on the rocks.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> laid</p><p><strong>解析：</strong> lay 表放置，过去式为 laid。</p></details><p><strong>表达迁移：</strong> 写三句模拟求助信息，给出地点、人数、无法移动的情况；不虚构真实救援呼叫。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The hikers laid bright jackets on the rocks to attract attention. A helicopter crew spotted the colours. The hikers signalled that one person could not walk.</p><p>第一句的组织方式：laid 为 lay 的过去式，bright jackets 是宾语，to attract 为目的状语，执行者与 hikers 一致。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：lie 表躺下，过去式 lay；lay 表放置，过去式 laid，本例需要有宾语的 laid。</p></details><p><a href="/life/english/new-concept/book-2/unit-04/lesson-075">回看本课</a></p><h2 id="lesson-76-·-间接引语与视角转换" tabindex="-1">Lesson 76 · 间接引语与视角转换 <a class="header-anchor" href="#lesson-76-·-间接引语与视角转换" aria-label="Permalink to &quot;Lesson 76 · 间接引语与视角转换 {#lesson-76-·-间接引语与视角转换}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The programme claimed that the trees could grow blue apples.</p><h3 id="练习-1-3" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-3" aria-label="Permalink to &quot;练习 1 {#练习-1-3}&quot;">​</a></h3><p>填 that/what：The report claimed ___ the fruit was blue.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> that</p><p><strong>解析：</strong> 从句结构完整，用 that 引出内容。</p></details><p><strong>表达迁移：</strong> 写一个识别虚构报道的过程，区分声称、核查和最后确认。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The programme claimed that the trees could grow blue apples. I checked the date before sharing it. The next programme explained that the story was a joke.</p><p>第一句的组织方式：claimed 为报告动词，that 从句是被声称的内容；could 是从过去视角表达能力，句子不证明该能力真实。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：believe a person 表相信其所说，believe in a person 更偏信任其能力或品格。</p></details><p><a href="/life/english/new-concept/book-2/unit-04/lesson-076">回看本课</a></p><h2 id="lesson-77-·-现在完成时与过去时间" tabindex="-1">Lesson 77 · 现在完成时与过去时间 <a class="header-anchor" href="#lesson-77-·-现在完成时与过去时间" aria-label="Permalink to &quot;Lesson 77 · 现在完成时与过去时间 {#lesson-77-·-现在完成时与过去时间}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The injured bird has recovered enough to stand on both feet.</p><h3 id="练习-1-4" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-4" aria-label="Permalink to &quot;练习 1 {#练习-1-4}&quot;">​</a></h3><p>填顺序：The bird is ___ to stand.（strong/enough）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> strong enough</p><p><strong>解析：</strong> enough 修饰形容词时放在后面。</p></details><p><strong>表达迁移：</strong> 写一段虚构救助记录，包含进展、仍有的限制和下一步评估。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The injured bird has recovered enough to stand on both feet. The carers still keep it indoors. They will assess its flight before releasing it.</p><p>第一句的组织方式：has recovered 为完成时，enough to stand 表达到某种程度，on both feet 说明动作状态。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：enough healthy 的次序不对；形容词后放 enough，如 healthy enough。</p></details><p><a href="/life/english/new-concept/book-2/unit-04/lesson-077">回看本课</a></p><h2 id="lesson-78-·-动名词与动词搭配" tabindex="-1">Lesson 78 · 动名词与动词搭配 <a class="header-anchor" href="#lesson-78-·-动名词与动词搭配" aria-label="Permalink to &quot;Lesson 78 · 动名词与动词搭配 {#lesson-78-·-动名词与动词搭配}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Jon stopped buying cigarettes on his way to work.</p><h3 id="练习-1-5" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-5" aria-label="Permalink to &quot;练习 1 {#练习-1-5}&quot;">​</a></h3><p>选 buying/to buy：He stopped ___ cigarettes.（不再购买）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> buying</p><p><strong>解析：</strong> 动名词指出被停止的活动。</p></details><p><strong>表达迁移：</strong> 描述一个准备改变的普通习惯，给出具体行动和追踪办法。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Jon stopped buying cigarettes on his way to work. He changed his route to avoid the shop. He asked a friend to check on his progress each week.</p><p>第一句的组织方式：stopped 为谓语，buying 作动名词宾语，on his way to work 是购买发生的情境。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：He stopped to buy cigarettes 表示停下来买烟，意思与停止买烟相反。</p></details><p><a href="/life/english/new-concept/book-2/unit-04/lesson-078">回看本课</a></p><h2 id="lesson-79-·-时间、原因与让步从句" tabindex="-1">Lesson 79 · 时间、原因与让步从句 <a class="header-anchor" href="#lesson-79-·-时间、原因与让步从句" aria-label="Permalink to &quot;Lesson 79 · 时间、原因与让步从句 {#lesson-79-·-时间、原因与让步从句}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Despite the delay, we enjoyed the view from the plane.</p><h3 id="练习-1-6" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-6" aria-label="Permalink to &quot;练习 1 {#练习-1-6}&quot;">​</a></h3><p>选 despite/although：___ the delay, we enjoyed the view.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Despite</p><p><strong>解析：</strong> 后面是名词短语 the delay。</p></details><p><strong>表达迁移：</strong> 写一段旅行体验，包含一个不便、一个值得欣赏的细节与一项限制。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Despite the delay, we enjoyed the view from the plane. Snow covered the mountains below. The seatbelt sign remained on until we reached smoother air.</p><p>第一句的组织方式：Despite the delay 是介词短语，主句 enjoyed 为过去式，from the plane 给出观察位置。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：despite it was late 结构不对；可用 despite the delay 或 although it was late。</p></details><p><a href="/life/english/new-concept/book-2/unit-04/lesson-079">回看本课</a></p><h2 id="lesson-80-·-被动语态与信息重点" tabindex="-1">Lesson 80 · 被动语态与信息重点 <a class="header-anchor" href="#lesson-80-·-被动语态与信息重点" aria-label="Permalink to &quot;Lesson 80 · 被动语态与信息重点 {#lesson-80-·-被动语态与信息重点}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The exhibition hall was built from glass and steel.</p><h3 id="练习-1-7" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-7" aria-label="Permalink to &quot;练习 1 {#练习-1-7}&quot;">​</a></h3><p>填 build 的过去分词：The hall was ___ in one year.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> built</p><p><strong>解析：</strong> build 的过去式和过去分词均为 built。</p></details><p><strong>表达迁移：</strong> 为虚构展馆写三句简介，说明建材、原用途和现在的遗存。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The exhibition hall was built from glass and steel. After the exhibition, parts of it were reused. A small section now stands in a public garden.</p><p>第一句的组织方式：was built 为一般过去被动，from glass and steel 说明建材；主语是展厅而非建造者。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：was build 错误，build 的过去分词是 built。</p></details><p><a href="/life/english/new-concept/book-2/unit-04/lesson-080">回看本课</a></p>',71)])])}const g=s(i,[["render",r]]);export{u as __pageData,g as default};
